import numpy as np
from numpy.random import Generator, PCG64
from scipy.stats import bootstrap, permutation_test, monte_carlo_test
nan = float('nan')
inf = float('inf')

def close(x, ref, rtol: float = 1e-9, atol: float = 1e-9) -> bool:
    a = np.asarray(x).astype(float)
    r = np.asarray(ref).astype(float)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if not (abs(u - v) <= atol + rtol * abs(v) or (u != u and v != v) or u == v):
            print('mismatch', u, v)
            ok = False
    return ok

b_bca = [3.058105363741663, 4.559608938589054, 0.38445434385273464]
b_misc = [-0.8666666666666667, 1.0627083333333331, 0.5182780512847847, -0.28770833333333357, 0.4249999999999994, 0.18987118636750278, -0.7392149215930596, 1.041666666666666, 0.542586036231801, -inf, 4.4, 0.5608107236684173]
b_ax = [[2.7724906743441493, 2.735289375495271, 2.2992689150479917], [5.392563861736484, 5.485748678110099, 5.03366119519429], [0.6674727370254399, 0.6957326515827269, 0.6835260671824571]]
b_dist = [100.0, 378.3916666666667]
perm = [0.09999999999999964, 0.886, 17.46666666666666, 0.31499999999999995, 0.746031746031746, 126.0, -1.3322676295501878e-15, 0.033333333333333215, 1.0, 64.0, 0.09999999999999964, 0.3153692614770459, 3.7416666666666667, 0.003992015968063872, 0.8633889342940982, 1.0, 0.7973513716565183, 0.14770459081836326, 500.0, -0.8763510473439999, 0.8381289192631041, -0.530149180354575, 0.46766169154228854, 0.46766169154228854, 0.5671641791044776]
mc = [3.7416666666666667, 0.003992015968063872, -7.108640089306055]

x = np.array([2.1, 3.4, 1.9, 5.6, 4.2, 3.3, 2.8, 6.1, 4.4, 3.9, 2.2, 5.0])
y = np.array([1.8, 2.9, 3.1, 4.7, 5.2, 2.6, 3.0, 5.9, 3.5, 4.1, 2.5, 4.4])
X2 = np.cos(np.arange(30.)).reshape(3, 10) * 3 + 4

def md(a, b, axis=-1):
    return np.mean(a, axis=axis) - np.mean(b, axis=axis)

def corr(a, b, axis=-1):
    am = a - np.mean(a, axis=axis, keepdims=True)
    bm = b - np.mean(b, axis=axis, keepdims=True)
    return np.sum(am*bm, axis=axis) / np.sqrt(np.sum(am*am, axis=axis)*np.sum(bm*bm, axis=axis))

def ci(r):
    return [np.asarray(r.confidence_interval.low), np.asarray(r.confidence_interval.high), np.asarray(r.standard_error)]

class Norm:
    g: Generator[PCG64]
    def __init__(self, seed: int):
        self.g = np.random.default_rng(seed)
    def __call__(self, size):
        return self.g.standard_normal(size)

@test
def test_bootstrap():
    r = bootstrap((x,), np.mean, n_resamples=500, rng=12)
    assert close(ci(r), b_bca)
    out = []
    r = bootstrap((x, y), md, n_resamples=500, rng=12, method='basic')
    out += ci(r)
    r = bootstrap((x, y), md, n_resamples=500, rng=12, method='percentile', paired=True)
    out += ci(r)
    r = bootstrap((x, y), md, n_resamples=300, rng=5, method='bca', confidence_level=0.9)
    out += ci(r)
    r = bootstrap((x,), np.median, n_resamples=300, rng=5, method='percentile', alternative='less', vectorized=True)
    out += ci(r)
    assert close(out, b_misc)
    r = bootstrap((X2,), np.mean, axis=1, n_resamples=200, rng=9, method='bca')
    assert close([r.confidence_interval.low, r.confidence_interval.high, r.standard_error], b_ax)
    r2 = bootstrap((x,), np.mean, n_resamples=100, rng=4, method='percentile')
    assert close([r2.bootstrap_distribution.shape[0], np.sum(r2.bootstrap_distribution)], b_dist)

@test
def test_permutation():
    out = []
    p = permutation_test((x, y), md, n_resamples=999, rng=3)
    out += [p.statistic, p.pvalue, p.null_distribution.sum()]
    p = permutation_test((x[:5], y[:4]), md, n_resamples=999, rng=3)
    out += [p.statistic, p.pvalue, p.null_distribution.shape[0], p.null_distribution.sum()]
    p = permutation_test((x[:6], y[:6]), md, permutation_type='samples', n_resamples=999, rng=3)
    out += [p.statistic, p.pvalue, p.null_distribution.shape[0]]
    p = permutation_test((x, y), md, permutation_type='samples', n_resamples=500, rng=3, alternative='greater')
    out += [p.statistic, p.pvalue]
    p = permutation_test((x,), np.mean, permutation_type='samples', n_resamples=500, rng=3)
    out += [p.statistic, p.pvalue]
    p = permutation_test((x, y), corr, permutation_type='pairings', n_resamples=500, rng=3, alternative='less')
    out += [p.statistic, p.pvalue]
    p = permutation_test((x[:5], y[:5]), corr, permutation_type='pairings', n_resamples=500, rng=3)
    out += [p.statistic, p.pvalue, p.null_distribution.shape[0]]
    p = permutation_test((X2[:, :5], X2[:, 5:]), md, n_resamples=200, rng=8, axis=1)
    out += list(p.statistic) + list(p.pvalue)
    assert close(out, perm)

@test
def test_monte_carlo():
    m = monte_carlo_test(x, Norm(7), np.mean, n_resamples=500, vectorized=True)
    assert close([m.statistic, m.pvalue, m.null_distribution.sum()], mc)

test_bootstrap()
test_permutation()
test_monte_carlo()
